# rubik_solve_asm: optimal 2x2x2 solver, hand-written RV32I.
#
# int rubik_solve_asm(const char *state, char *out, size_t cap)
#     a0 = state, a1 = out, a2 = cap -> a0 = moves, -1 or -2
#
# RV32I and Zicsr only: no mul, div, rem, no floating point, no compressed
# instructions. Tests: tests/trubik.c. Tables: rubik_data.S, generated by
# gen_tables.py.
#
# The algorithm is the one of rubik.c: a state is the permutation rank p
# (0..5039) and the orientation rank o (0..728), moved by transition tables;
# states within 5 moves of solved are answered by near[], states at distance
# 11 step to a neighbor at distance 10 first, and iterative deepening runs a
# depth-first search to depth bound - 5 that ends in a lookup of near[]. What
# the assembly adds:
#
#   * The tables are laid out for the addressing: four halfwords per rank,
#     so the entry of face f is at base + (rank << 3) + (f << 1), no multiply.
#   * near[] is searched only within the bucket of its key (key >> 12), found
#     through nidx[]: about 10 entries, at most 22, instead of 12,224.
#   * A near[] entry is (key << 3) | distance, so with T = key << 3 the first
#     entry e >= T is a hit exactly when e - T < 8, and then e - T is the
#     distance: one subtraction both tests and decodes.
#   * Internal routines share a convention of their own: a4..a7 carry the
#     search constants through every recursive call untouched, and the table
#     lookups use only t0..t6, so the depth-first search saves nothing for
#     them.
#
# Internal convention, set by rubik_solve_asm before the search:
#   a4 = &moves[len], where the depth-first search writes its moves
#   a5 = limit, the depth at which near[] is asked
#   a6 = rubik_asm_pn, a7 = rubik_asm_on

    .equ    NO_FACE, 3
    .equ    NEAR_SHIFT, 12          # must match gen_tables.py
    .equ    RUBIK_FAR_COUNT, 2644   # the states at distance 11

    # Frame of rubik_solve_asm.
    .equ    F_CUBIE, 0              # 7 places, 0-based
    .equ    F_TWIST, 8              # 7 twists, 0-based
    .equ    F_MOVES, 16             # up to 11 moves, face * 3 + turns - 1
    .equ    F_SIZE, 96

# Apply one quarter turn of face f to the ranks q and t.
    .macro  STEP q, t, f
    slli    t0, \q, 3
    add     t0, t0, a6
    slli    t1, \f, 1
    add     t0, t0, t1
    lhu     \q, 0(t0)
    slli    t0, \t, 3
    add     t0, t0, a7
    add     t0, t0, t1
    lhu     \t, 0(t0)
    .endm

# a0 = (q << 10) | t, the key of a state.
    .macro  KEY q, t
    slli    a0, \q, 10
    or      a0, a0, \t
    .endm

    .text

    .globl  rubik_solve_asm
    .type   rubik_solve_asm, @function
    .align  2
rubik_solve_asm:
    addi    sp, sp, -F_SIZE
    sw      ra, 92(sp)
    sw      s0, 88(sp)
    sw      s1, 84(sp)
    sw      s2, 80(sp)
    sw      s3, 76(sp)
    sw      s4, 72(sp)
    sw      s5, 68(sp)
    sw      s6, 64(sp)
    sw      s7, 60(sp)
    sw      s8, 56(sp)
    sw      s9, 52(sp)
    sw      s10, 48(sp)
    sw      s11, 44(sp)
    mv      s11, a0                 # state
    mv      s9, a1                  # out
    mv      s10, a2                 # cap

    # --- Validate and parse -------------------------------------------
    # Exactly 14 characters: none of the first 14 is NUL, the 15th is.
    li      t0, 0
    li      t2, 14
.Lp_len:
    add     t1, s11, t0
    lbu     t1, 0(t1)
    beqz    t1, .Linvalid
    addi    t0, t0, 1
    bne     t0, t2, .Lp_len
    lbu     t1, 14(s11)
    bnez    t1, .Linvalid

    # Places '1'..'7', each once: a bit mask of the cubies seen.
    li      t3, 0
    li      t0, 0
    li      t2, 7
.Lp_place:
    add     t1, s11, t0
    lbu     t1, 0(t1)
    addi    t1, t1, -'1'
    bgeu    t1, t2, .Linvalid       # unsigned: below '1' wraps high
    li      t4, 1
    sll     t4, t4, t1
    and     t5, t3, t4
    bnez    t5, .Linvalid           # a repeated cubie
    or      t3, t3, t4
    add     t5, sp, t0
    sb      t1, F_CUBIE(t5)
    addi    t0, t0, 1
    bne     t0, t2, .Lp_place

    # Twists '1'..'3' summing (less one each) to a multiple of 3.
    li      t3, 0
    li      t0, 0
    li      t4, 3
.Lp_twist:
    add     t1, s11, t0
    lbu     t1, 7(t1)
    addi    t1, t1, -'1'
    bgeu    t1, t4, .Linvalid
    add     t3, t3, t1
    add     t5, sp, t0
    sb      t1, F_TWIST(t5)
    addi    t0, t0, 1
    bne     t0, t2, .Lp_twist
.Lp_mod3:                           # the sum is at most 14
    bltu    t3, t4, .Lp_mod3_done
    addi    t3, t3, -3
    j       .Lp_mod3
.Lp_mod3_done:
    bnez    t3, .Linvalid

    # --- Ranks ----------------------------------------------------------
    # p: for each place, the later places holding a smaller cubie, as a
    # mixed-radix number of radix 7, 6, ..., 1. The radix is at most 7, so
    # the multiply is a few additions.
    li      s0, 0
    li      t0, 0                   # i
.Lr_place:
    add     t5, sp, t0
    lbu     t1, F_CUBIE(t5)         # cubie at i
    li      t3, 0                   # smaller
    addi    t4, t0, 1               # j
.Lr_later:
    bgeu    t4, t2, .Lr_counted
    add     t6, sp, t4
    lbu     t6, F_CUBIE(t6)
    sltu    t6, t6, t1
    add     t3, t3, t6
    addi    t4, t4, 1
    j       .Lr_later
.Lr_counted:
    sub     t4, t2, t0              # radix 7 - i
    mv      t6, s0
    li      s0, 0
.Lr_times:
    add     s0, s0, t6
    addi    t4, t4, -1
    bnez    t4, .Lr_times
    add     s0, s0, t3
    addi    t0, t0, 1
    bne     t0, t2, .Lr_place

    # o: the first six twists in base 3.
    li      s1, 0
    li      t0, 0
    li      t2, 6
.Lr_twist:
    add     t5, sp, t0
    lbu     t1, F_TWIST(t5)
    slli    t3, s1, 1
    add     s1, s1, t3              # o * 3
    add     s1, s1, t1
    addi    t0, t0, 1
    bne     t0, t2, .Lr_twist

    la      a6, rubik_asm_pn
    la      a7, rubik_asm_on
    li      s2, 0                   # moves made so far
    li      s3, NO_FACE             # face of the last of them

    # --- Within 5 moves: walk down near[] ---------------------------------
    KEY     s0, s1
    call    near_dist
    mv      s4, a0
    bgez    a0, .Ldescend

    # --- At distance 11: one move to a neighbor at distance 10 -------------
    KEY     s0, s1
    call    is_far
    beqz    a0, .Lsearch
    li      s5, 0                   # face
.Lfar_face:
    mv      s6, s0
    mv      s7, s1
    li      s8, 0                   # quarter turns - 1
.Lfar_turn:
    STEP    s6, s7, s5
    KEY     s6, s7
    call    is_far
    beqz    a0, .Lfar_found
    addi    s8, s8, 1
    li      t0, 3
    bne     s8, t0, .Lfar_turn
    addi    s5, s5, 1
    j       .Lfar_face              # some neighbor is always at 10
.Lfar_found:
    slli    t0, s5, 1
    add     t0, t0, s5
    add     t0, t0, s8
    sb      t0, F_MOVES(sp)
    li      s2, 1
    mv      s0, s6
    mv      s1, s7
    mv      s3, s5

    # --- Iterative deepening: bound = 6, 7, ..., limit = bound - 5 ----------
.Lsearch:
    addi    a4, sp, F_MOVES
    add     a4, a4, s2
    li      a5, 1
.Lbound:
    mv      a0, s0
    mv      a1, s1
    li      a2, 0
    mv      a3, s3
    call    dfs
    bnez    a0, .Lfound
    addi    a5, a5, 1
    j       .Lbound
.Lfound:
    mv      s0, a1                  # the state where near[] answered
    mv      s1, a2
    add     s2, s2, a5
    KEY     s0, s1
    call    near_dist
    mv      s4, a0

    # --- Walk down near[]: s4 moves left from (s0, s1) -----------------------
.Ldescend:
    beqz    s4, .Lemit
    li      s5, 0                   # face
.Ld_face:
    mv      s6, s0
    mv      s7, s1
    li      s8, 0                   # quarter turns - 1
.Ld_turn:
    STEP    s6, s7, s5
    KEY     s6, s7
    call    near_dist
    addi    t0, s4, -1
    beq     a0, t0, .Ld_found
    addi    s8, s8, 1
    li      t0, 3
    bne     s8, t0, .Ld_turn
    addi    s5, s5, 1
    j       .Ld_face                # some move always gets one closer
.Ld_found:
    slli    t0, s5, 1
    add     t0, t0, s5
    add     t0, t0, s8
    add     t1, sp, s2
    sb      t0, F_MOVES(t1)
    addi    s2, s2, 1
    mv      s0, s6
    mv      s1, s7
    addi    s4, s4, -1
    j       .Ldescend

    # --- Text: "R", "R2" or "R'" per move, single spaces, NUL ---------------
.Lemit:
    la      t5, move_suffix
    li      t3, 1                   # bytes needed: the NUL
    li      t0, 0
.Le_count:
    beq     t0, s2, .Le_counted
    add     t1, sp, t0
    lbu     t1, F_MOVES(t1)
    add     t1, t1, t5
    lbu     t1, 0(t1)
    snez    t1, t1                  # a suffix takes a byte
    add     t3, t3, t1
    addi    t3, t3, 1               # the face letter
    snez    t1, t0
    add     t3, t3, t1              # a space before every move but the first
    addi    t0, t0, 1
    j       .Le_count
.Le_counted:
    bgeu    s10, t3, .Le_write
    beqz    s10, .Le_short          # cap 0: out is never written
    sb      zero, 0(s9)
.Le_short:
    li      a0, -2
    j       .Lreturn
.Le_write:
    la      t4, move_face
    mv      t2, s9                  # write pointer
    li      t0, 0
.Le_move:
    beq     t0, s2, .Le_done
    beqz    t0, .Le_first
    li      t1, ' '
    sb      t1, 0(t2)
    addi    t2, t2, 1
.Le_first:
    add     t1, sp, t0
    lbu     t1, F_MOVES(t1)
    add     t6, t1, t4
    lbu     t6, 0(t6)
    sb      t6, 0(t2)
    addi    t2, t2, 1
    add     t6, t1, t5
    lbu     t6, 0(t6)
    beqz    t6, .Le_next
    sb      t6, 0(t2)
    addi    t2, t2, 1
.Le_next:
    addi    t0, t0, 1
    j       .Le_move
.Le_done:
    sb      zero, 0(t2)
    mv      a0, s2
    j       .Lreturn

.Linvalid:
    li      a0, -1
.Lreturn:
    lw      ra, 92(sp)
    lw      s0, 88(sp)
    lw      s1, 84(sp)
    lw      s2, 80(sp)
    lw      s3, 76(sp)
    lw      s4, 72(sp)
    lw      s5, 68(sp)
    lw      s6, 64(sp)
    lw      s7, 60(sp)
    lw      s8, 56(sp)
    lw      s9, 52(sp)
    lw      s10, 48(sp)
    lw      s11, 44(sp)
    addi    sp, sp, F_SIZE
    ret
    .size   rubik_solve_asm, .-rubik_solve_asm

# dfs: a0 = p, a1 = o, a2 = depth, a3 = face of the previous move.
# Makes limit - depth more moves, never the previous face again, writing move
# d to a4[d]. Returns a0 = 1 with a1, a2 = the state reached when near[]
# answers at depth limit, else a0 = 0. Keeps a4..a7.
    .type   dfs, @function
    .align  2
dfs:
    addi    sp, sp, -48
    sw      ra, 44(sp)
    sw      s0, 40(sp)
    sw      s1, 36(sp)
    sw      s3, 32(sp)
    sw      s4, 28(sp)
    sw      s5, 24(sp)
    sw      s6, 20(sp)
    sw      s7, 16(sp)
    sw      s8, 12(sp)
    sw      s9, 8(sp)
    mv      s0, a0                  # p
    mv      s1, a1                  # o
    mv      s3, a3                  # previous face
    add     s6, a4, a2              # &moves[depth]
    addi    s7, a2, 1               # depth of the children
    li      s4, 0                   # face
.Ldfs_face:
    beq     s4, s3, .Ldfs_next_face
    mv      s8, s0                  # q
    mv      s9, s1                  # t
    li      s5, 0                   # quarter turns - 1
.Ldfs_turn:
    STEP    s8, s9, s4
    slli    t0, s4, 1
    add     t0, t0, s4
    add     t0, t0, s5
    sb      t0, 0(s6)
    bne     s7, a5, .Ldfs_inner
    KEY     s8, s9                  # a leaf: ask near[]
    call    near_dist
    bltz    a0, .Ldfs_next_turn
    mv      a1, s8
    mv      a2, s9
    li      a0, 1
    j       .Ldfs_return
.Ldfs_inner:
    mv      a0, s8
    mv      a1, s9
    mv      a2, s7
    mv      a3, s4
    call    dfs
    bnez    a0, .Ldfs_return        # a1, a2 hold the state found
.Ldfs_next_turn:
    addi    s5, s5, 1
    li      t0, 3
    bne     s5, t0, .Ldfs_turn
.Ldfs_next_face:
    addi    s4, s4, 1
    li      t0, 3
    bne     s4, t0, .Ldfs_face
    li      a0, 0
.Ldfs_return:
    lw      ra, 44(sp)
    lw      s0, 40(sp)
    lw      s1, 36(sp)
    lw      s3, 32(sp)
    lw      s4, 28(sp)
    lw      s5, 24(sp)
    lw      s6, 20(sp)
    lw      s7, 16(sp)
    lw      s8, 12(sp)
    lw      s9, 8(sp)
    addi    sp, sp, 48
    ret
    .size   dfs, .-dfs

# near_dist: a0 = key -> a0 = distance when within 5 moves, else -1.
# Lower bound of T = key << 3 within the bucket nidx[key >> 12]; the entry
# found is a hit when it minus T is below 8, and that difference is the
# distance. Uses t0..t6 only.
    .type   near_dist, @function
    .align  2
near_dist:
    la      t0, rubik_asm_nidx
    srli    t1, a0, NEAR_SHIFT
    slli    t1, t1, 1
    add     t0, t0, t1
    lhu     t1, 0(t0)               # lo
    lhu     t2, 2(t0)               # hi
    la      t3, rubik_asm_near
    slli    t4, a0, 3               # T
    bgeu    t1, t2, .Lnd_check
.Lnd_loop:
    add     t5, t1, t2
    srli    t5, t5, 1               # mid
    slli    t6, t5, 2
    add     t6, t6, t3
    lw      t6, 0(t6)
    bgeu    t6, t4, .Lnd_upper
    addi    t1, t5, 1               # near[mid] < T: look right
    bltu    t1, t2, .Lnd_loop
    j       .Lnd_check
.Lnd_upper:
    mv      t2, t5                  # near[mid] >= T: look left, mid included
    bltu    t1, t2, .Lnd_loop
.Lnd_check:
    slli    t6, t1, 2
    add     t6, t6, t3
    lw      t6, 0(t6)               # the first entry >= T, or the sentinel
    sub     t5, t6, t4
    li      a0, -1
    sltiu   t0, t5, 8
    beqz    t0, .Lnd_return
    mv      a0, t5
.Lnd_return:
    ret
    .size   near_dist, .-near_dist

# is_far: a0 = key -> a0 = 1 when the state is at distance 11, else 0.
# Lower bound over all of far[]; called at most ten times a solve.
# Uses t0..t6 only.
    .type   is_far, @function
    .align  2
is_far:
    la      t3, rubik_asm_far
    li      t1, 0                   # lo
    li      t2, RUBIK_FAR_COUNT     # hi
.Lif_loop:
    bgeu    t1, t2, .Lif_check
    add     t5, t1, t2
    srli    t5, t5, 1
    slli    t6, t5, 2
    add     t6, t6, t3
    lw      t6, 0(t6)
    bgeu    t6, a0, .Lif_upper
    addi    t1, t5, 1
    j       .Lif_loop
.Lif_upper:
    mv      t2, t5
    j       .Lif_loop
.Lif_check:
    slli    t6, t1, 2
    add     t6, t6, t3
    lw      t6, 0(t6)
    sub     t6, t6, a0
    seqz    a0, t6
    ret
    .size   is_far, .-is_far

    .section .rodata
move_face:
    .byte   'R', 'R', 'R', 'B', 'B', 'B', 'D', 'D', 'D'
move_suffix:
    .byte   0, '2', '\'', 0, '2', '\'', 0, '2', '\''
